import requests
from pathlib import Path
import zipfile

# Constants
DOWNLOAD_DIR = Path("downloads")
ZIP_DIR = Path("unzipped_files")

def task_func(url, filename):
    """
    Downloads a zip file from a specified URL and extracts it.

    Args:
        url (str): The URL of the zip file.
        filename (str): The name to save the downloaded zip file as.

    Returns:
        tuple: A tuple containing a status message and a list of filenames 
               in the unzipped directory, or an empty list if extraction fails.
    """
    # Create necessary directories
    try:
        DOWNLOAD_DIR.mkdir(parents=True, exist_ok=True)
        ZIP_DIR.mkdir(parents=True, exist_ok=True)
    except Exception as e:
        return (f"Error: Could not create directories. {e}", [])

    zip_file_path = DOWNLOAD_DIR / filename

    # Download the file
    try:
        response = requests.get(url, stream=True, timeout=30)
        response.raise_for_status()
        with open(zip_file_path, 'wb') as f:
            for chunk in response.iter_content(chunk_size=8192):
                f.write(chunk)
    except requests.exceptions.RequestException as e:
        return (f"Error: Network-related exception occurred. {e}", [])
    except Exception as e:
        return (f"Error: File-related exception during download. {e}", [])

    # Extract the file
    try:
        with zipfile.ZipFile(zip_file_path, 'r') as zip_ref:
            zip_ref.extractall(ZIP_DIR)
            extracted_files = zip_ref.namelist()
        return ("Success: File downloaded and extracted.", extracted_files)
    except zipfile.BadZipFile:
        return ("Error: File is not a zip file or is corrupted.", [])
    except Exception as e:
        return (f"Error: File-related exception during extraction. {e}", [])

